(43761, 'Genesis 24:46', 'Genesis', 24, 46, 'هغې زر خپل منګی د اوږو څخه راښکته کړ او ویې ویل: ‹وڅښه. زه به ستا اوښانو ته هم اوبه ورکړم.› نو بیا ما وڅښلې او هغې اوښانو ته هم اوبه ورکړې.', 'هغې زر خپل منګی د اوزو چخه راشکته کر او ویې ویل: ‹وچشه. زه به ستا اوشانو ته هم اوبه ورکرم.› نو بیا ما وچشلې او هغې اوشانو ته هم اوبه ورکرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_46.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43762, 'Genesis 24:47', 'Genesis', 24, 47, 'د هغې څخه مې پوښتنه وکړه: ‹ته د چا لور یې؟› نو هغې وویل: ‹زه د بتوییل لور یم او د ناحور او میلکه لمسۍ یم.› نو د هغې په پوزه کې مې پېزوان واچاوه او په لاسونو کې مې ورته کړۍ‌ګانې واچولې.', 'د هغې چخه مې پوشتنه وکره: ‹ته د چا لور یې؟› نو هغې وویل: ‹زه د بتوییل لور یم او د ناحور او میلکه لمسی یم.› نو د هغې په پوزه کې مې پېزوان واچاوه او په لاسونو کې مې ورته کری‌ګانې واچولې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_47.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43763, 'Genesis 24:48', 'Genesis', 24, 48, 'ما سجده وکړه او د څښتن عبادت مې وکړ او د خپل بادار ابراهیم څښتن خدای مې وستایه چې ماته یې سمه لاره وښودله چې د خپل بادار د ورور لمسۍ د هغه زوی ته وکړم.', 'ما سجده وکره او د چشتن عبادت مې وکر او د خپل بادار ابراهیم چشتن خدای مې وستایه چې ماته یې سمه لاره وشودله چې د خپل بادار د ورور لمسی د هغه زوی ته وکرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_48.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43764, 'Genesis 24:49', 'Genesis', 24, 49, 'نو اوس که چېرې زما د بادار سره وفاداري او تلپاتې مینه کوې هم راته ووایه او که نه یې کوې هم ماته ووایه، ترڅو زه پرېکړه وکړم چې بل چېرته لاړ شم.»', 'نو اوس که چېرې زما د بادار سره وفاداری او تلپاتې مینه کوې هم راته ووایه او که نه یې کوې هم ماته ووایه، ترچو زه پرېکره وکرم چې بل چېرته لار شم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_49.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43765, 'Genesis 24:50', 'Genesis', 24, 50, 'لابان او بتوییل ځواب ورکړ: «څرنګه چې دا خبره د څښتن له خوا ده، نو مونږ په دې هکله پرېکړه نه شو کولای.', 'لابان او بتوییل جواب ورکر: «چرنګه چې دا خبره د چشتن له خوا ده، نو مونز په دې هکله پرېکره نه شو کولای.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_50.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43766, 'Genesis 24:51', 'Genesis', 24, 51, 'دا دی ربکا حاضره ده هغه درسره واخله او ځه. لکه څنګه چې څښتن په خپله ویلي دي، هغه دې ستا د بادار د زوی ښځه شي.»', 'دا دی ربکا حاضره ده هغه درسره واخله او جه. لکه چنګه چې چشتن په خپله ویلی دی، هغه دې ستا د بادار د زوی شجه شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_51.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43767, 'Genesis 24:52', 'Genesis', 24, 52, 'څنګه چې د ابراهیم ناظر دا خبره واورېدله، نو سجده یې وکړه او د څښتن عبادت یې وکړ.', 'چنګه چې د ابراهیم ناظر دا خبره واورېدله، نو سجده یې وکره او د چشتن عبادت یې وکر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_52.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43768, 'Genesis 24:53', 'Genesis', 24, 53, 'بیا ناظر کالي، د سپینو زرو او سرو زرو ګاڼې راوویستل او ربکا ته یې ورکړل او د هغې ورور او مور ته یې هم قیمتي سوغاتونه ورکړل.', 'بیا ناظر کالی، د سپینو زرو او سرو زرو ګانې راوویستل او ربکا ته یې ورکرل او د هغې ورور او مور ته یې هم قیمتی سوغاتونه ورکرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_53.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43769, 'Genesis 24:54', 'Genesis', 24, 54, 'بیا د ابراهیم ناظر او د هغه کسانو وخوړل او وڅښل او شپه یې هلته تېره کړه. کله چې هغوی سهار پاڅېدل، ناظر وویل: «ما رخصت کړه چې بېرته خپل بادار ته لاړ شم.»', 'بیا د ابراهیم ناظر او د هغه کسانو وخورل او وچشل او شپه یې هلته تېره کره. کله چې هغوی سهار پاچېدل، ناظر وویل: «ما رخصت کره چې بېرته خپل بادار ته لار شم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_54.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43770, 'Genesis 24:55', 'Genesis', 24, 55, 'خو د ربکا ورور او مور وویل: «انجلۍ دې یوه هفته یا لس ورځې زمونږ سره پاتې شي، بیا تاسو کولای شئ چې لاړ شئ.»', 'خو د ربکا ورور او مور وویل: «انجلی دې یوه هفته یا لس ورجې زمونز سره پاتې شی، بیا تاسو کولای شی چې لار شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_55.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43771, 'Genesis 24:56', 'Genesis', 24, 56, 'خو هغه وویل: «مونږ مه ایساروئ. څښتن زما سفر بریالی کړی دی، پرېږدئ چې بېرته خپل بادار ته لاړ شم.»', 'خو هغه وویل: «مونز مه ایساروی. چشتن زما سفر بریالی کری دی، پرېزدی چې بېرته خپل بادار ته لار شم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_56.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43772, 'Genesis 24:57', 'Genesis', 24, 57, 'هغوی وویل: «راځئ چې انجلۍ راوغواړو او په دې هکله د هغې څخه پوښتنه وکړو.»', 'هغوی وویل: «راجی چې انجلی راوغوارو او په دې هکله د هغې چخه پوشتنه وکرو.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_57.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43773, 'Genesis 24:58', 'Genesis', 24, 58, 'نو هغوی ربکا راوغوښتله او پوښتنه یې ترې وکړه: «ایا د دې سړي سره ځې؟» هغې وویل: «هو، ځم.»', 'نو هغوی ربکا راوغوشتله او پوشتنه یې ترې وکره: «ایا د دې سری سره جې؟» هغې وویل: «هو، جم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_58.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43774, 'Genesis 24:59', 'Genesis', 24, 59, 'نو هغوی خپله خور ربکا او د هغې زړه نوکره د ابراهیم د ناظر او د هغه د کسانو سره ولېږلې.', 'نو هغوی خپله خور ربکا او د هغې زره نوکره د ابراهیم د ناظر او د هغه د کسانو سره ولېزلې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_59.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43775, 'Genesis 24:60', 'Genesis', 24, 60, 'هغوی د ربکا دپاره برکت وغوښت او ورته یې وویل: ای زمونږ خورې! ته دې شې مور د میلیونونو اولادونو فتح دې کړي ښارونه ستا اولاده د دښمنانو خپلو', 'هغوی د ربکا دپاره برکت وغوشت او ورته یې وویل: ای زمونز خورې! ته دې شې مور د میلیونونو اولادونو فتح دې کری شارونه ستا اولاده د دشمنانو خپلو', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_60.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43776, 'Genesis 24:61', 'Genesis', 24, 61, 'بیا ربکا او د هغې وینځې تیارې شوې او په اوښانو باندې سپرې شوې او د سړي سره روانې شوې. نو ناظر ربکا د ځان سره واخیستله او لاړ.', 'بیا ربکا او د هغې وینجې تیارې شوې او په اوشانو باندې سپرې شوې او د سری سره روانې شوې. نو ناظر ربکا د جان سره واخیستله او لار.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_61.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43777, 'Genesis 24:62', 'Genesis', 24, 62, 'په دې وخت کې اسحاق د بئرلحي ریي څخه راغلی ؤ او د کنعان په جنوب کې اوسېده.', 'په دې وخت کې اسحاق د بیرلحی ریی چخه راغلی و او د کنعان په جنوب کې اوسېده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_62.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43778, 'Genesis 24:63', 'Genesis', 24, 63, 'یو ماښام اسحاق په پټیو کې چکر واهه. څنګه چې هغه خپلې سترګې پورته کړې ویې لیدل چې اوښان راروان دي.', 'یو ماشام اسحاق په پتیو کې چکر واهه. چنګه چې هغه خپلې سترګې پورته کرې ویې لیدل چې اوشان راروان دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_63.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43779, 'Genesis 24:64', 'Genesis', 24, 64, 'ربکا هم خپلې سترګې پورته کړې او اسحاق یې ولیده، نو د اوښ څخه راښکته شوه', 'ربکا هم خپلې سترګې پورته کرې او اسحاق یې ولیده، نو د اوش چخه راشکته شوه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_64.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43780, 'Genesis 24:65', 'Genesis', 24, 65, 'او د ناظر څخه یې پوښتنه وکړه: «هغه سړی څوک دی چې په پټي کې زمونږ خوا ته راروان دی؟» ناظر ځواب ورکړ: «هغه زما بادار دی.» نو هغې خپل څادر راواخیست او خپل ځان یې ورباندې پټ کړ.', 'او د ناظر چخه یې پوشتنه وکره: «هغه سری چوک دی چې په پتی کې زمونز خوا ته راروان دی؟» ناظر جواب ورکر: «هغه زما بادار دی.» نو هغې خپل چادر راواخیست او خپل جان یې ورباندې پت کر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_65.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43781, 'Genesis 24:66', 'Genesis', 24, 66, 'کوم کارونه چې ناظر کړي وو، هغه ټول یې اسحاق ته بیان کړل.', 'کوم کارونه چې ناظر کری وو، هغه تول یې اسحاق ته بیان کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_66.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43782, 'Genesis 24:67', 'Genesis', 24, 67, 'اسحاق ربکا د خپلې مور ساره خېمې ته راوستله او د هغې سره یې واده وکړ. نو ربکا د هغه ښځه شوه او د هغې سره یې مینه کوله او اسحاق د خپلې مور د مړینې څخه وروسته تسلي وموندله.', 'اسحاق ربکا د خپلې مور ساره خېمې ته راوستله او د هغې سره یې واده وکر. نو ربکا د هغه شجه شوه او د هغې سره یې مینه کوله او اسحاق د خپلې مور د مرینې چخه وروسته تسلی وموندله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_24_67.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43783, 'Ruth 3:1', 'Ruth', 3, 1, 'څه موده وروسته نعومي روت ته وویل: «ای زما لورې زه باید ستا دپاره مېړه پیدا کړم، هغه به تاته کور درکړي او په تا به پام کوي.', 'چه موده وروسته نعومی روت ته وویل: «ای زما لورې زه باید ستا دپاره مېره پیدا کرم، هغه به تاته کور درکری او په تا به پام کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_3_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43784, 'Ruth 3:2', 'Ruth', 3, 2, 'ته پوهېږې چې بوعز زمونږ خپلوان دی او تا د هغو ښځو سره وږي راټول کړي دي چې د هغه دپاره کار کوي. ګوره، نن شپه به هغه په درمند باندې اوربشې بادوي.', 'ته پوهېزې چې بوعز زمونز خپلوان دی او تا د هغو شجو سره وزی راتول کری دی چې د هغه دپاره کار کوی. ګوره، نن شپه به هغه په درمند باندې اوربشې بادوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_3_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43785, 'Ruth 3:3', 'Ruth', 3, 3, 'اوس ولامبه او لږ عطر په ځان واچوه، بیا خپلې ښې جامې واغونده او درمند ته لاړه شه. خو ترڅو پورې چې هغه د خوراک او څښاک څخه وزګار شوی نه وي، خپل ځان مه ورښکاره کوه.', 'اوس ولامبه او لز عطر په جان واچوه، بیا خپلې شې جامې واغونده او درمند ته لاره شه. خو ترچو پورې چې هغه د خوراک او چشاک چخه وزګار شوی نه وی، خپل جان مه ورشکاره کوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ruth_3_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
